<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller;use App\Services\AuditService;use App\Support\LegacyResponse;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Throwable;
class GeneralShiftJobController extends Controller
{
 public function __construct(private AuditService $audit){} private function user(Request $r){return $r->attributes->get('jwt_user');}
 private function number(string $plant,string $dept):string{$pc=strtoupper(preg_replace('/\s+/','',$plant?:'CMMS'));$dc=strtoupper(substr($dept?:'GEN',0,3));$count=DB::table('general_shift_jobs')->where('plant',$plant)->whereYear('created_at',now()->year)->count()+1;return "$pc-$dc-GSJ-".str_pad((string)$count,4,'0',STR_PAD_LEFT);}
 public function index(Request $r){try{$u=$this->user($r);$q=DB::table('general_shift_jobs as g')->leftJoin('users as u1','u1.id','=','g.raised_by')->leftJoin('users as u2','u2.id','=','g.closed_by')->select('g.*','u1.full_name as raised_by_name','u2.full_name as closed_by_name');if($u->role==='maintenance')$q->where('g.department',$u->department);if($r->filled('plant'))$q->where('g.plant',$r->input('plant'));if($r->filled('status'))$q->where('g.status',$r->input('status'));$rows=$q->orderByRaw("CASE g.status WHEN 'OPEN' THEN 1 WHEN 'IN PROGRESS' THEN 2 WHEN 'COMPLETED' THEN 3 WHEN 'CLOSED' THEN 4 ELSE 5 END")->orderByDesc('g.created_at')->limit(200)->get()->map(fn($x)=>LegacyResponse::normalize($x))->all();return response()->json(['success'=>true,'data'=>$rows]);}catch(Throwable $e){return $this->err($e);}}
 public function store(Request $r){if(!$r->input('title'))return response()->json(['success'=>false,'message'=>'Title is required'],400);if(!$r->input('plant'))return response()->json(['success'=>false,'message'=>'Plant is required'],400);$u=$this->user($r);if(!$u->department)return response()->json(['success'=>false,'message'=>'User has no department assigned'],400);try{$no=$this->number($r->input('plant'),$u->department);$id=DB::table('general_shift_jobs')->insertGetId(['job_number'=>$no,'title'=>$r->input('title'),'description'=>$r->input('description')?:null,'department'=>$u->department,'plant'=>$r->input('plant'),'expected_completion_date'=>$r->input('expected_completion_date')?:null,'remarks'=>$r->input('remarks')?:null,'photos'=>$r->has('photos')?json_encode($r->input('photos')):null,'raised_by'=>$u->id,'raised_by_name'=>$u->full_name??null,'status'=>'OPEN','created_at'=>now(),'updated_at'=>now()]);$row=DB::table('general_shift_jobs')->where('id',$id)->first();$this->audit->log($u->id,'CREATE_GSJ','general_shift_jobs',$id,['job_number'=>$no,'title'=>$r->input('title'),'department'=>$u->department,'plant'=>$r->input('plant')],$r->ip());return response()->json(['success'=>true,'data'=>LegacyResponse::normalize($row),'message'=>'General shift job raised successfully'],201);}catch(Throwable $e){return $this->err($e);}}
 public function status(Request $r,$id){$status=$r->input('status');$valid=['IN PROGRESS','COMPLETED','CLOSED'];if(!in_array($status,$valid,true))return response()->json(['success'=>false,'message'=>'Status must be IN PROGRESS, COMPLETED, or CLOSED'],400);try{$job=DB::table('general_shift_jobs')->where('id',$id)->first();if(!$job)return response()->json(['success'=>false,'message'=>'Job not found'],404);$u=$this->user($r);if($u->role!=='admin'&&$job->department!==$u->department)return response()->json(['success'=>false,'message'=>'You can only update your own department jobs'],403);$trans=['OPEN'=>['IN PROGRESS'],'IN PROGRESS'=>['COMPLETED'],'COMPLETED'=>['CLOSED'],'CLOSED'=>[]];if(!in_array($status,$trans[$job->status]??[],true))return response()->json(['success'=>false,'message'=>'Invalid status transition: '.$job->status.' → '.$status.'. Allowed: '.implode(', ',$trans[$job->status]??[])],400);$data=['status'=>$status,'remarks'=>$r->input('remarks')?:$job->remarks,'updated_at'=>now()];if($status==='IN PROGRESS')$data['started_at']=now();elseif($status==='COMPLETED')$data['completed_at']=now();else{$data['closed_at']=now();$data['closed_by']=$u->id;}DB::table('general_shift_jobs')->where('id',$id)->update($data);$row=DB::table('general_shift_jobs')->where('id',$id)->first();$this->audit->log($u->id,'GSJ_'.str_replace(' ','_',$status),'general_shift_jobs',$id,['status'=>$status,'remarks'=>$r->input('remarks')],$r->ip());return response()->json(['success'=>true,'data'=>LegacyResponse::normalize($row),'message'=>'Job updated to '.$status]);}catch(Throwable $e){return $this->err($e);}}
 public function show($id){try{$row=DB::table('general_shift_jobs as g')->leftJoin('users as u1','u1.id','=','g.raised_by')->leftJoin('users as u2','u2.id','=','g.closed_by')->select('g.*','u1.full_name as raised_by_name','u2.full_name as closed_by_name')->where('g.id',$id)->first();if(!$row)return response()->json(['success'=>false,'message'=>'Job not found'],404);return response()->json(['success'=>true,'data'=>LegacyResponse::normalize($row)]);}catch(Throwable $e){return $this->err($e);}}
 public function destroy(Request $r,$id){try{DB::table('general_shift_jobs')->where('id',$id)->delete();$this->audit->log($this->user($r)->id,'DELETE_GSJ','general_shift_jobs',$id,[],$r->ip());return response()->json(['success'=>true,'message'=>'Job deleted']);}catch(Throwable $e){return $this->err($e);}}
 private function err(Throwable $e){return response()->json(['success'=>false,'message'=>$e->getMessage()],500);}
}
